<source_code>
#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define F first
#define S second
#define mp make_pair
#define pii pair<int,int>
#define vi vector<int>
#define pq priority_queue
#define pb push_back
#define watch(x) cout << (#x) << " is " << (x) << endl
#define ALL(a) (a.begin()),(a.end())
#define FOR(x,to) for(ll x=0;x<(to);x++)
#define FORR(x,to) for(ll x=1;x<=(to);x++)
#define fastio ios::sync_with_stdio(0); cin.tie(NULL);
const int INF = 0x3f3f3f3f;
const int MOD = 1e9+7;


ll expo(ll x, ll a){
    if(a==0) return 1;
    ll ans = expo(x,a/2);

    ans *= ans;
    ans %= MOD;
    if(a%2) {

        ans *= x;
        ans %= MOD;
    } 
    return ans;
}


int main(){
	fastio;
    ll p, k;
    cin >> p >> k;

    if(k == 0){
        cout << expo(p,p-1) << "\n";
    }
    else if(k == 1){
        cout << expo(p,p) << "\n";
    }
    else{
        ll at = k;
        ll fator = 1;
        while(at!=1){

            at = (at*k)%p;
            fator++;
        }

        ll expoente = (p-1)/fator;

        cout << expo(p,expoente) << "\n";

    }

    }
